from bisect import bisect_left


def lcsDistinctValues(a, b):
    pos = {v: i for i, v in enumerate(a)}
    tails = []
    for v in b:
        i = pos.get(v)
        if i is None:
            continue
        k = bisect_left(tails, i)
        if k == len(tails):
            tails.append(i)
        else:
            tails[k] = i
    return len(tails)
